'use strict';

// MODULES //

var isBigInt = require( '@stdlib/assert/is-bigint' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isUint64 = require( '@stdlib/assert/is-uint64' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns an array of iterated values.
*
* @private
* @param {Object} it - iterator
* @returns {(Array|TypeError)} array or an error
*/
function fromIterator( it ) {
	var out;
	var v;
	var u;

	out = [];
	while ( true ) {
		v = it.next();
		if ( v.done ) {
			break;
		}
		u = v.value;
		if ( !isUint64( u ) ) {
			if ( !isNonNegativeInteger( u ) && !isBigInt( u ) ) {
				return new TypeError( format( 'invalid argument. An iterator must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer. Value: `%s`.', u ) );
			}
			u = new Uint64( u );
		}
		out.push( u.hi, u.lo );
	}
	return out;
}


// EXPORTS //

module.exports = fromIterator;
